import {connect, Contract, keyStores, WalletConnection} from 'near-api-js';
import {setupWalletSelector} from "@near-wallet-selector/core";
import {setupModal} from "@near-wallet-selector/modal-ui";
import {setupMyNearWallet} from "@near-wallet-selector/my-near-wallet";
import {setupMeteorWallet} from "@near-wallet-selector/meteor-wallet";
import {setupHereWallet} from "@near-wallet-selector/here-wallet";
import {setupSender} from "@near-wallet-selector/sender";
import {useGlobalState, useGlobalMutation} from './utils/container'
import 'regenerator-runtime/runtime';
import "@near-wallet-selector/modal-ui/styles.css";

import getConfig from './config'
const nearConfig = getConfig(process.env.NODE_ENV || 'development')

export async function initContract() {
  const near = await connect(Object.assign({deps: {keyStore: new keyStores.BrowserLocalStorageKeyStore()}}, nearConfig))

  // Initialize wallet selector
  const selector = await setupWalletSelector({
    network: nearConfig.networkId,
    modules: [
      setupMyNearWallet(),
      setupMeteorWallet(),
      setupHereWallet(),
      setupSender(),
    ],
  });

  const modal = setupModal(selector, {
    contractId: nearConfig.contractName,
  });

  window.selector = selector;
  window.modal = modal;

  // Get current wallet and accounts
  const isSignedIn = selector.isSignedIn();
  let accountId = '';

  if (isSignedIn) {
    const wallet = await selector.wallet();
    const accounts = await wallet.getAccounts();
    accountId = accounts.length > 0 ? accounts[0].accountId : '';
  }

  window.accountId = accountId;

  // Create wallet connection for backward compatibility
  window.walletConnection = {
    isSignedIn: () => selector.isSignedIn(),
    getAccountId: () => window.accountId,
    account: () => {
      if (!window.accountId) {
        throw new Error('Wallet not connected');
      }
      return near.account(window.accountId);
    },
    signOut: async () => {
      const wallet = await selector.wallet();
      await wallet.signOut();
      window.accountId = '';
    },
    requestSignIn: async (contractId) => {
      modal.show();
    }
  };

  if (isSignedIn) {
    window.factoryContract = await new Contract(window.walletConnection.account(), nearConfig.contractName, {
      viewMethods: ['get_dao_list'],
      changeMethods: ['create'],
    })
  }
}

export async function logout() {
  if (window.selector) {
    const wallet = await window.selector.wallet();
    await wallet.signOut();
    window.accountId = '';
  }
  window.location.replace(window.location.origin + window.location.pathname)
}

export function login() {
  if (window.modal) {
    window.modal.show();
  }
}
